@Override
	public void onUpdate() {
		if(!this.world.isRemote && (this.world.getDifficulty() == EnumDifficulty.PEACEFUL || (this.getOwner() != null && !this.getOwner().isEntityAlive()))) {
			this.setDead();
			return;
		}

		this.setTriangleSize(this.getTriangleSize());

		this.motionX = 0;
		this.motionY = 0;
		this.motionZ = 0;

		super.onUpdate();

		if(!this.world.isRemote) {
			this.despawnTicks++;
			if(this.despawnTicks >= this.getMaxDespawnTicks()) {
				this.setDead();
			}

			this.rotation += 1.0F;
			this.getDataManager().set(ROTATION, this.rotation);

			List<EntityLivingBase> targets = this.world.getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox().grow(this.getTriangleSize()*2, 0, this.getTriangleSize()*2));
			for(EntityLivingBase target : targets) {
				if(target != this.getOwner()) {
					Vec3d[] vertices = this.getTriangleVertices(1);

					if(EntityFortressBoss.rayTraceTriangle(new Vec3d(target.posX - this.posX, 1, target.posZ - this.posZ), new Vec3d(0, -2, 0), vertices[0], vertices[1], vertices[2])) {

						if(this.isPlayerControlled()) {
							IPuppetCapability cap = target.getCapability(CapabilityRegistry.CAPABILITY_PUPPET, null);

							Entity owner = this.getOwner();

							if(cap != null && cap.getPuppeteer() == owner && owner instanceof EntityPlayer) {
								EntityPlayer player = (EntityPlayer) owner;

								IPuppeteerCapability playerCap = player.getCapability(CapabilityRegistry.CAPABILITY_PUPPETEER, null);
								if(playerCap != null) {
									ProtectionShield shield = playerCap.getShield();

									if(shield != null) {
										float healthPercent = 0.3f;

										if(target.getHealth() * (1 - healthPercent) > 5.0f) {
											float healthCost = target.getHealth() * healthPercent;
											float prevHealth = target.getHealth();

											if(target.attackEntityFrom(DamageSource.MAGIC, healthCost) && (prevHealth - target.getHealth()) >= healthCost * 0.5f) {
												List<Integer> indices = new ArrayList<>();
												for(int i = 0; i < 20; i++) {
													indices.add(i);
												}
												Collections.shuffle(indices, this.rand);

												for(int index : indices) {
													if(!shield.isActive(index)) {
														shield.setActive(index, true);
														break;
													}
												}

												this.maxDespawnTicks = this.despawnTicks + 8;
											}
										}
									}
								}
							}
						} else if(target instanceof EntityPlayer)  {
							float damage = (float) this.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue();
							if(target.attackEntityFrom(DamageSource.MAGIC, damage) && this.getOwner() != null && this.getOwner() instanceof EntityLivingBase) {
								EntityLivingBase owner = (EntityLivingBase) this.getOwner();
								if(owner.getHealth() < owner.getMaxHealth() - damage) {
									owner.heal(damage * 3.0F);
								}
							}
						}

					}
				}
			}
		} else {
			this.prevRotation = this.rotation;
			this.rotation = this.getDataManager().get(ROTATION);

			for(int c = 0; c < 4; c++) {
				float r1 = this.world.rand.nextFloat();
				float r2 = this.world.rand.nextFloat();
				this.rotation += 15;
				Vec3d[] vertices = this.getTriangleVertices(1);
				this.rotation -= 15;
				double xc = 0, zc = 0;
				for(int i = 0; i < 3; i++) {
					Vec3d vertex = vertices[i];
					switch(i) {
					default:
					case 0:
						xc += vertex.x * (1 - Math.sqrt(r1));
						zc += vertex.z * (1 - Math.sqrt(r1));
						break;
					case 1:
						xc += (Math.sqrt(r1) * (1 - r2)) * vertex.x;
						zc += (Math.sqrt(r1) * (1 - r2)) * vertex.z;
						break;
					case 2:
						xc += (Math.sqrt(r1) * r2) * vertex.x;
						zc += (Math.sqrt(r1) * r2) * vertex.z;
						break;
					}
				}
				Vec3d rp = new Vec3d(xc, vertices[0].y, zc);

				double sx = this.posX + rp.x;
				double sy = this.posY + rp.y + 4;
				double sz = this.posZ + rp.z;
				double ex = this.posX + rp.x;
				double ey = this.posY + rp.y;
				double ez = this.posZ + rp.z;

				if(this.getOwner() != null) {
					sx = this.getOwner().posX;
					sy = this.getOwner().getEntityBoundingBox().minY + (this.getOwner().getEntityBoundingBox().maxY - this.getOwner().getEntityBoundingBox().minY) / 2.0D;
					sz = this.getOwner().posZ;
				}

				if(!this.isPlayerControlled()) {
					this.world.spawnParticle(EnumParticleTypes.PORTAL, sx, sy, sz, ex - sx, ey - sy, ez - sz);
				}
			}
		}
	}

@Nullable
	public Entity getOwner() {
		UUID uuid = this.getOwnerUUID();
		if(uuid == null) {
			this.cachedOwner = null;
		} else if(this.cachedOwner == null || !this.cachedOwner.isEntityAlive() || !this.cachedOwner.getUniqueID().equals(uuid)) {
			this.cachedOwner = null;
			for(Entity entity : this.getEntityWorld().getEntitiesWithinAABB(Entity.class, this.getEntityBoundingBox().grow(64.0D, 64.0D, 64.0D))) {
				if(entity.getUniqueID().equals(uuid)) {
					this.cachedOwner = entity;
					break;
				}
			}
		}
		return this.cachedOwner;
	}

@Override
	public void writeEntityToNBT(NBTTagCompound nbt) {
		super.writeEntityToNBT(nbt);
		nbt.setFloat("triangleSize", this.getTriangleSize());
		nbt.setFloat("triangleRotation", this.getDataManager().get(ROTATION));
		nbt.setInteger("despawnTicks", this.despawnTicks);
		nbt.setInteger("maxDespawnTicks", this.maxDespawnTicks);
		if(this.getOwnerUUID() != null) {
			nbt.setUniqueId("owner", this.getOwnerUUID());
		}
	}

@Override
	public void readEntityFromNBT(NBTTagCompound nbt) {
		super.readEntityFromNBT(nbt);
		this.setTriangleSize(nbt.getFloat("triangleSize"));
		this.getDataManager().set(ROTATION, nbt.getFloat("triangleRotation"));
		this.despawnTicks = nbt.getInteger("despawnTicks");
		this.maxDespawnTicks = nbt.getInteger("maxDespawnTicks");
		if(nbt.hasUniqueId("owner")) {
			this.getDataManager().set(OWNER, Optional.of(nbt.getUniqueId("owner")));
		} else {
			this.getDataManager().set(OWNER, Optional.absent());
		}
	}

public Vec3d[] getTriangleVertices(float partialTicks) {
		Vec3d[] vertices = new Vec3d[3];
		double rot = Math.toRadians(this.prevRotation + (this.rotation - this.prevRotation) * partialTicks);
		double angle = Math.PI * 2.0D / 3.0D;
		for(int i = 0; i < 3; i++) {
			double sin = Math.sin(angle * i + rot);
			double cos = Math.cos(angle * i + rot);
			vertices[i] = new Vec3d(sin * this.getTriangleSize(), 0, cos * this.getTriangleSize());
		}
		return vertices;
	}

public void tick() {
        super.tick();
        if (!this.isActivated()){
            int count = SpellConfig.RuptureDuration.get() / 3;
            if (this.tickCount % count == 0) {
                if (this.level.isClientSide) {
                    if (this.getAnimation() < 2) {
                        this.setAnimation(this.getAnimation() + 1);
                    }
                }
                this.playSound(ModSounds.RUMBLE.get(), 2.0F, this.random.nextFloat() + 0.75F);
            }
        } else {
            if (this.level.isClientSide) {
                if (this.tickCount % 20 == 0) {
                    if (this.isClosing) {
                        if (this.getAnimation() > 0) {
                            this.setAnimation(this.getAnimation() - 1);
                        }
                    } else {
                        if (this.getAnimation() < 7) {
                            this.setAnimation(this.getAnimation() + 1);
                        } else {
                            this.setAnimation(3);
                        }
                    }
                }
            }
        }
        if (!this.level.isClientSide) {
            if (this.warmUp <= 0) {
                if (!this.isActivated()) {
                    this.setActivated(true);
                    this.level.broadcastEntityEvent(this, (byte) 100);
                }
                if (!this.playEvent) {
                    this.playSound(ModSounds.VOID_RIFT_OPEN.get(), 5.0F, 1.0F);
                    ModNetwork.sendToALL(new SPlayLoopSoundPacket(this, ModSounds.VOID_RIFT.get(), 5.0F, 1.0F));
                    this.playEvent = true;
                }
                if (this.tickCount % 200 == 0){
                    this.playSound(SoundEvents.PORTAL_AMBIENT, 5.0F, 0.75F);
                }
                List<Entity> targets = new ArrayList<>();
                float range = 16.0F * (this.getSize() + 1.0F);
                /*if (!this.isClosing) {
                    int rangeInt = Mth.floor(range);
                    this.suckBlocks(rangeInt, rangeInt, rangeInt);
                }*/
                if (this.level instanceof ServerLevel serverWorld) {
                    ServerParticleUtil.gatheringParticles(ParticleTypes.PORTAL, this, serverWorld, (int)range);
                }
                for (Entity entity : this.level.getEntitiesOfClass(Entity.class, this.getBoundingBox().inflate(range))) {
                    if (!(entity instanceof Endermite)) {
                        if (entity instanceof ModFallingBlock modFallingBlock && modFallingBlock.getMode() == ModFallingBlock.FallingBlockMode.DEBRIS){
                            targets.add(entity);
                            if (entity.distanceTo(this) <= 1.0F){
                                entity.discard();
                            }
                        }
                        if (this.getOwner() != null) {
                            if (!MobUtil.areAllies(this.getOwner(), entity) && MobUtil.getOwner(entity) != this.getOwner()) {
                                targets.add(entity);
                            }
                        } else {
                            targets.add(entity);
                        }
                    }
                }
                if (!targets.isEmpty()) {
                    for (Entity entity : targets) {
                        double distance = 1.0D - (entity.distanceTo(this) / range);
                        double scale = distance * 0.25D;
                        Vec3 vec3 = entity.position().subtract(this.position());
                        vec3 = vec3.normalize().scale(scale);
                        MobUtil.pull(entity, vec3.x, vec3.y, vec3.z, 0.5D);
                        if (entity.distanceTo(this) <= this.getBoundingBox().getSize()){
                            if (entity instanceof LivingEntity livingEntity) {
                                float damage = SpellConfig.RuptureDamage.get().floatValue() * WandUtil.damageMultiply();
                                if (this.getOwner() != null) {
                                    if (this.getOwner() instanceof Mob mob && mob.getAttribute(Attributes.ATTACK_DAMAGE) != null) {
                                        damage = (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE) / 2.0F;
                                    }
                                }
                                damage += this.getExtraDamage();
                                livingEntity.hurt(this.damageSources().indirectMagic(this, this.getOwner()), damage);
                            }
                        }
                    }
                }
            } else {
                if (this.level instanceof ServerLevel serverWorld) {
                    double d1 = this.getX() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth();
                    double d2 = this.getY() + 0.5F;
                    double d3 = this.getZ() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth();
                    serverWorld.sendParticles(ParticleTypes.PORTAL, d1, d2, d3, 0, 0.0D, 0.0D, 0.0D, 0.5F);
                }
                if (this.getOwner() != null && this.getOwner().isDeadOrDying()) {
                    this.discard();
                }
                --this.warmUp;
            }
            if (this.tickCount >= this.getDuration()) {
                if (!this.isClosing){
                    this.isClosing = true;
                    this.level.broadcastEntityEvent(this, (byte) 101);
                }
                if (this.tickCount >= this.getDuration() + 20) {
                    if (this.level instanceof ServerLevel serverLevel) {
                        ColorUtil colorUtil = new ColorUtil(0x7317d2);
                        float range = 8.0F * (this.getSize() + 1.0F);
                        serverLevel.sendParticles(new ShockwaveParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, range, 0, true), this.getX(), this.getY() + 0.5D, this.getZ(), 0, 0, 0, 0, 0);
                        ServerParticleUtil.createParticleBall(ParticleTypes.DRAGON_BREATH, this.getX(), this.getY() + 0.5D, this.getZ(), serverLevel,  8 + (int) this.getSize());
                        this.playSound(SoundEvents.RESPAWN_ANCHOR_DEPLETE.get(), 5.0F, 0.5F);
                        this.playSound(SoundEvents.GENERIC_EXPLODE, 5.0F, 0.5F);
                        new SpellExplosion(this.level, this.getOwner() != null ? this.getOwner() : this, this.damageSources().indirectMagic(this, this.getOwner()), this.blockPosition(), range / 4, 0.0F) {
                            @Override
                            public void explodeHurt(Entity target, DamageSource damageSource, double x, double y, double z, double seen, float actualDamage) {
                                super.explodeHurt(target, damageSource, x, y, z, seen, actualDamage);
                                if (VoidRift.this.isStaff()) {
                                    if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(target)) {
                                        if (target instanceof LivingEntity livingEntity) {
                                            livingEntity.addEffect(new MobEffectInstance(GoetyEffects.VOID_TOUCHED.get(), MathHelper.secondsToTicks(5), 2, false, true));
                                        }
                                    }
                                }
                            }
                        };
                    }
                    this.discard();
                }
            }
        }
    }

public void readAdditionalSaveData(CompoundTag compound) {
        super.readAdditionalSaveData(compound);
        if (compound.contains("Size")) {
            this.setSize(compound.getFloat("Size"));
        }
        if (compound.contains("TickTime")) {
            this.tickCount = compound.getInt("TickTime");
        }
        if (compound.contains("WarmUp")) {
            this.warmUp = compound.getInt("WarmUp");
        }
        if (compound.contains("PlayEvent")) {
            this.playEvent = compound.getBoolean("PlayEvent");
        }
        if (compound.contains("IsClosing")) {
            this.isClosing = compound.getBoolean("IsClosing");
        }
    }

public void addAdditionalSaveData(CompoundTag compound) {
        super.addAdditionalSaveData(compound);
        compound.putFloat("Size", this.getSize());
        compound.putInt("TickTime", this.tickCount);
        compound.putInt("WarmUp", this.warmUp);
        compound.putBoolean("PlayEvent", this.playEvent);
        compound.putBoolean("IsClosing", this.isClosing);
    }

public void setWarmUp(int warmUp){
        this.warmUp = warmUp;
        this.setDuration(this.getDuration() + warmUp);
    }

@Override
    public void handleEntityEvent(byte p_19882_) {
        if (p_19882_ == 100){
            this.setActivated(true);
            this.setAnimation(3);
        } else if (p_19882_ == 101){
            this.isClosing = true;
            this.setAnimation(2);
        } else {
            super.handleEntityEvent(p_19882_);
        }
    }

@Override
    public void tick() {
        super.tick();
        if (this.level instanceof ServerLevel serverWorld) {
            if (this.getParticle() != null) {
                ServerParticleUtil.circularParticles(serverWorld, this.getParticle(), this.getX(), this.getY(), this.getZ(), this.radius());
            }
